using System.IO;
using System.Text.Json;
using VisionCore;
using VisionPlugins.Calibration;
const string folder="analysis/map-calibration/image-grid-workspace-trace";var rows=File.ReadAllLines(folder+"/grid-trace.jsonl").Select(s=>JsonDocument.Parse(s)).ToArray();var reports=new List<object>();int group=0;bool failed=false;
foreach(var doc in rows){var row=doc.RootElement;if(row.GetProperty("stage").GetInt32()!=0)continue;int imageIndex=group%2;var image=new GrayImage(1000,1000,File.ReadAllBytes($"analysis/map-calibration/image-preprocess-trace/raw-{imageIndex*3+1:D3}.gray"));var actual=NImageSourceGridPyramid.Find(image);var points=row.GetProperty("points");int exact=0;var differences=new List<object>();for(int i=0;i<Math.Min(points.GetArrayLength(),actual.Points.Count);i++){var p=actual.Points[i];var e=points[i];bool same=BitConverter.SingleToInt32Bits(p.X)==BitConverter.SingleToInt32Bits(e[0].GetSingle())&&BitConverter.SingleToInt32Bits(p.Y)==BitConverter.SingleToInt32Bits(e[1].GetSingle())&&p.Column==e[2].GetInt32()&&p.Row==e[3].GetInt32();if(same)exact++;else if(differences.Count<10)differences.Add(new{i,p,expected=e.Clone()});}bool success=actual.Points.Count==points.GetArrayLength()&&exact==actual.Points.Count&&actual.Width==row.GetProperty("dimensions")[0].GetInt32()&&actual.Height==row.GetProperty("dimensions")[1].GetInt32();failed|=!success;reports.Add(new{group,count=actual.Points.Count,exact,actual.Width,actual.Height,actual.Score,success,differences});Console.WriteLine($"Pyramid{group}: {exact}/{actual.Points.Count}/{points.GetArrayLength()} success={success}");group++;}
foreach(var d in rows)d.Dispose();Directory.CreateDirectory("analysis/map-calibration/grid-pyramid");File.WriteAllText("analysis/map-calibration/grid-pyramid/comparison.json",JsonSerializer.Serialize(new{cases=reports.Count,failed,reports},new JsonSerializerOptions{WriteIndented=true}));return failed||reports.Count!=4?1:0;
